import {PARAMS} from './project.js';
export const ENGINE_NAMES=['ANALOG','FM','ORGAN','PLUCK','SAMPLER','CLUSTER','DIGITAL','PULSE','PHASE','WAVE','DUAL ENVELOPE','VOLTAGE','DNA'];
export const ENGINE_INFO=[['SAW / PULSE','Detuned band-limited waveforms.'],['FOUR OPERATORS','Nested FM with ratio and feedback colour.'],['DRAWBARS','Additive harmonics and tone.'],['EXCITED STRING','A noise-excited waveguide.'],['SAMPLE REGIONS','Your audio, with pitched playback, loop and reverse.'],['OSCILLATOR CLOUD','Seven independent detuned oscillators.'],['FOLD / RING','Ring modulation, folding and digital resolution.'],['PULSE TRAINS','Cross-modulated pulse oscillators.'],['PHASE MAP','Breakpoint phase distortion with harmonic modulation.'],['SPECTRAL WAVES','Sixteen partials with spectral morph and tilt.'],['DUAL CURRENT','Cross-modulating sine and saw oscillators.'],['INDUCTION','Feedback phase synthesis and saturating waveshaping.'],['CLOCKED NOISE','Seeded digital noise and a pitched carrier.']];
export const OPTIONS={fxType:['BYPASS','DELAY / MAGNET','GRID / LATTICE','NITRO / RESONANT','PHONE / TELECOM','PUNCH / IMPACT','SPRING / COIL','CWO / SIDEBAND'],fxRoute:['SOURCE → TAPE','MASTER → OUTPUT'],modType:['OFF','SINE','TRIANGLE','RANDOM / HOLD','VELOCITY','MIDI CC 1','ENVELOPE FOLLOW'],modTarget:['TONE','SHAPE','PITCH','DEVICE FX'],seqType:['PATTERN','ENDLESS','FINGER','TOMBOLA','SKETCH','ARPEGGIO'],seqDirection:['FORWARD','REVERSE','RANDOM'],playMode:['POLY','MONO','ONE SHOT'],sampleLoop:['ONE SHOT','LOOP'],sampleReverse:['FORWARD','REVERSE'],drumMode:['D-BOX / SYNTH','YOUR SAMPLE / 8 SLICES']};
export const GROUPS=[['sound','ENVELOPE / PLAY',['attack','decay','sustainLevel','release','playMode']],['sound','SAMPLE / REGIONS',['sampleStart','sampleEnd','sampleLoop','sampleReverse']],['sound','EFFECT / ROUTING',['fxType','fxRoute','fxA','fxB','fxC','fxMix']],['sound','MODULATION',['modType','modTarget','modRate','modDepth']],['drums','DRUM DEVICE',['drumMode','drumPitch','drumDecay','drumColour','drumShape']],['sequence','SEQUENCER DEVICE',['seqType','seqLength','seqDirection','seqGate','seqOctaves','gravity']],['mix-page','MASTER / EQ',['eqLow','eqMid','eqHigh','compressor']],['mix-page','EFFECT / ROUTING',['fxType','fxRoute','fxA','fxB','fxC','fxMix']]];
export function mountDevices(setParam){for(const [page,title,ids]of GROUPS){const section=document.createElement('details');section.className='device-controls';section.open=page==='sequence'||page==='drums';const summary=document.createElement('summary');summary.textContent=title;section.append(summary);const grid=document.createElement('div');grid.className='device-grid';section.append(grid);for(const id of ids){const [,label,lo,hi]=PARAMS.find(p=>p[0]===id),wrap=document.createElement('label'),text=document.createElement('span');text.textContent=label.toUpperCase();wrap.append(text);let input;if(OPTIONS[id]){input=document.createElement('select');OPTIONS[id].forEach((label,i)=>{let o=document.createElement('option');o.value=i;o.textContent=label;input.append(o);});}else{input=document.createElement('input');input.type='number';input.min=lo;input.max=hi;input.step=['seqLength','seqOctaves'].includes(id)?1:id==='modRate'?.05:.01;}input.dataset.param=id;input.ariaLabel=label;input.onchange=()=>setParam(id,+input.value);wrap.append(input);grid.append(wrap);}document.getElementById(page).append(section);}}
